<?php require_once __DIR__.'/comman/auth.php'; $pageTitle="Add / Edit Game"; require __DIR__.'/comman/header.php'; require __DIR__.'/comman/sidebar.php'; ?><div class="content-wrapper"><section class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-8"><h1><?=h($pageTitle)?></h1></div></div><?php if($flash):?><div class="alert alert-<?=h($flash[0])?>"><?=h($flash[1])?></div><?php endif;?></div></section><section class="content"><div class="container-fluid"><?php $all=read_json(SITE_ROOT.'/data/games.json',[]);$edit=slugify($_GET['edit']??'');$g=null;foreach($all as $x){if(($x['slug']??'')===$edit){$g=$x;break;}}if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$slug=slugify(post_str('slug')?:post_str('name'));$old=slugify(post_str('old_slug'));$g=['id'=>$slug,'name'=>post_str('name'),'category'=>post_str('category','Yono Game'),'bonus'=>post_str('bonus'),'withdraw'=>post_str('withdraw'),'image'=>safe_url(post_str('image')),'url'=>safe_url(post_str('url')),'seoTitle'=>post_str('seoTitle'),'metaDescription'=>post_str('metaDescription'),'slug'=>$slug,'ogImage'=>safe_url(post_str('ogImage')?:post_str('image')),'description'=>post_str('description'),'faq'=>[],'button'=>post_str('button','View Game'),'status'=>bool_post('status'),'featured'=>bool_post('featured'),'popular'=>bool_post('popular'),'new_game'=>bool_post('new_game'),'page_link'=>'games/'.$slug.'/index.html'];if(!$g['name']||!$g['metaDescription'])flash('danger','Game name and meta description are required.');else{$all=array_values(array_filter($all,fn($x)=>($x['slug']??'')!==($old?:$slug)));$all[]=$g;write_json(SITE_ROOT.'/data/games.json',$all);$dir=SITE_ROOT.'/games/'.$slug;if(!is_dir($dir))mkdir($dir,0755,true);file_put_contents($dir.'/index.html',render_game($g),LOCK_EX);update_sitemap(game_page_url($g));flash('success','Game saved and SEO page generated.');redirect_admin('games.php');}}$g=$g?:['name'=>'','slug'=>'','category'=>'Yono Game','bonus'=>'','withdraw'=>'','image'=>'','url'=>'','seoTitle'=>'','metaDescription'=>'','ogImage'=>'','description'=>'','button'=>'View Game','status'=>true,'featured'=>false,'popular'=>false,'new_game'=>true];?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="old_slug" value="<?=h($g['slug'])?>"><div class="row"><div class="col-md-8"><div class="card"><div class="card-header"><h3 class="card-title">Game Information</h3></div><div class="card-body"><div class="form-group"><label>Game Name</label><input class="form-control" name="name" value="<?=h($g['name'])?>" required></div><div class="form-group"><label>Slug</label><input class="form-control" name="slug" value="<?=h($g['slug'])?>"></div><div class="form-group"><label>Category</label><input class="form-control" name="category" value="<?=h($g['category'])?>"></div><div class="form-group"><label>Game Image URL</label><input class="form-control" name="image" value="<?=h($g['image'])?>"></div><div class="form-group"><label>Game / Download URL</label><input class="form-control" name="url" value="<?=h($g['url'])?>"></div><div class="form-group"><label>Bonus / Offer Text</label><input class="form-control" name="bonus" value="<?=h($g['bonus'])?>"></div><div class="form-group"><label>Withdrawal Information</label><input class="form-control" name="withdraw" value="<?=h($g['withdraw'])?>"></div><div class="form-group"><label>Description</label><textarea class="form-control" name="description" rows="7"><?=h($g['description'])?></textarea></div></div></div><div class="card"><div class="card-header"><h3 class="card-title">SEO</h3></div><div class="card-body"><div class="form-group"><label>SEO Title</label><input class="form-control" name="seoTitle" value="<?=h($g['seoTitle'])?>" maxlength="70"></div><div class="form-group"><label>Meta Description</label><textarea class="form-control" name="metaDescription" rows="3" maxlength="160" required><?=h($g['metaDescription'])?></textarea></div><div class="form-group"><label>OG Image URL</label><input class="form-control" name="ogImage" value="<?=h($g['ogImage'])?>"></div></div></div></div><div class="col-md-4"><div class="card"><div class="card-header"><h3 class="card-title">Publishing</h3></div><div class="card-body"><div class="form-group"><label>Button Text</label><input class="form-control" name="button" value="<?=h($g['button'])?>"></div><?php foreach(['status'=>'Active','featured'=>'Featured','popular'=>'Popular','new_game'=>'New Game'] as $id=>$lab):?><div class="custom-control custom-checkbox mb-2"><input class="custom-control-input" id="<?=$id?>" type="checkbox" name="<?=$id?>" <?=!empty($g[$id])?'checked':''?>><label class="custom-control-label" for="<?=$id?>"><?=$lab?></label></div><?php endforeach;?><button class="btn btn-pink btn-block mt-3">Save & Generate SEO Page</button></div></div></div></div></form></div></section></div><?php require __DIR__.'/comman/footer.php'; ?>